import{_ as i,a0 as a,w as s,s as u,I as t,x as r,a1 as p,A as o,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Larry Wall 專訪——語言學、Perl 6 的設計和發佈 | LCTT x X-CMD","titleTemplate":false,"description":"Larry Wall 專訪——語言學、Perl 6 的設計和發佈 | LCTT (201510) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Larry Wall 專訪——語言學、Perl 6 的設計和發佈 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Larry Wall 專訪——語言學、Perl 6 的設計和發佈 | LCTT (201510) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201510/20150716 Interview--Larry Wall","title":"Larry Wall 專訪——語言學、Perl 6 的設計和發佈","tag":"201510","desc":""},"relativePath":"201510/20150716 Interview--Larry Wall.md","filePath":"[post].md"}'),P={name:"201510/20150716 Interview--Larry Wall.md"};function d(g,l,m,f,w,T){const e=a("Link");return s(),u("div",null,[l[27]||(l[27]=t("h1",{id:"larry-wall-專訪——語言學、perl-6-的設計和發佈",tabindex:"-1"},[r("Larry Wall 專訪——語言學、Perl 6 的設計和發佈 "),t("a",{class:"header-anchor",href:"#larry-wall-專訪——語言學、perl-6-的設計和發佈","aria-label":"Permalink to “Larry Wall 專訪——語言學、Perl 6 的設計和發佈”"},"​")],-1)),l[28]||(l[28]=t("blockquote",null,[t("p",null,"經歷了15年的打造，Perl 6 終將在年底與大家見面。我們預先採訪了它的作者瞭解一下新特性。")],-1)),t("p",null,[l[1]||(l[1]=r("Larry Wall 是個相當有趣的人。他是編程語言 Perl 的創造者，這種語言被廣泛的譽為將互聯網粘在一起的膠水，也由於大量地在各種地方使用非字母的符號被嘲笑為‘只寫’語言——以難以閲讀著稱。Larry 本人具有語言學背景，以其介紹 Perl 未來發展的演講“",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Perl#State_of_the_Onion"},{default:o(()=>[...l[0]||(l[0]=[r("洋葱的狀態",-1)])]),_:1}),l[2]||(l[2]=r("（State of the Onion）”而聞名。（LCTT 譯註：“洋葱的狀態”是 Larry Wall 的年度演講的主題，洋葱也是 Perl 基金會的標誌。）",-1))]),l[29]||(l[29]=n('<p>在2015年布魯塞爾的 FOSDEM 上，我們趕上了 Larry，問了問他為什麼 Perl 6 花了如此長的時間（Perl 5 的發佈時間是1994年），瞭解當項目中的每個人都各執己見時是多麼的難以管理，以及他的語言學背景自始至終究竟給 Perl 帶來了怎樣的影響。做好準備，讓我們來領略其中的奧妙……</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/07/wall1.jpg" alt=""></p><p><strong>Linux Voice：你曾經有過計劃去尋找世界上某個地方的某種不見經傳的語言，然後為它創造書寫的文字，但你從未有機會去實現它。如果你能回到過去，你會去做麼？</strong></p><p>Larry Wall：你首先得是個年輕人才能搞得定！做這些事需要投入很大的努力和人力，以至於已經不適合那些上了年紀的人了。健康、活力是其中的一部分，同樣也因為人們在年輕的時候更容易學習一門新的語言，只有在你學會了語言之後你才能寫呀。</p><p>我自學了日語十年，由於我的音系學和語音學的訓練我能説的比較流利——但要理解別人的意思對我來説還十分困難。所以到了日本我會問路，但我聽不懂他們的回答！</p><p>通常需要一門語言學習得足夠好才能開發一個文字體系，並可以使用這種語言進行少量的交流。在你能夠實際推廣它和用本土人自己的文化教育他們前，那還需要一些年。最後才可以教授本土人如何以他們的文明書寫。</p><p>當然如果在語言方面你有幫手 —— 經過別人的提醒我們不再使用“語言線人”來稱呼他們了，那樣顯得我們像是在 CIA 工作的一樣！—— 你可以通過他們的幫助來學習外語。他們不是老師，但他們會以另一種方式來啓發你學習 —— 當然他們也能教你如何説。他們會拿着一根棍子，指着它説“這是一根棍子”，然後丟掉同時説“棒子掉下去了”。然後，你就可以記下一些東西並將其系統化。</p><p>大多數讓人們有這樣做的動力是翻譯聖經。但是這只是其中的一方面；另一方面也是為了文化保護。傳教士在這方面臭名昭著，因為人類學家認為人們應該基於自己的文明來做這件事。但有些人註定會改變他們的文化——他們可能是軍隊、或是商業侵入，如可口可樂或者縫紉機，或傳教士。在這三者之間，傳教士相對來講傷害最小的了，如果他們恪守本職的話。</p><p><strong>LV：許多文字系統有本可依，相較而言你的發明就像是格林蘭語…</strong></p><p>印第安人照搬字母就發明了他們自己的語言，而且沒有在這些字母上施加太多我們給這些字母賦予的涵義，這種做法相當隨性。它們只要能夠表達出人們的所思所想，使交流順暢就行。經常是有些聲調語言（Tonal language）使用的是西方文字拼寫，並儘可能的使用拉丁文的字符變化，然後用重音符或數字標註出音調。</p><p>在你開始學習如何使用語音和語調錶示之後，你也開始變得迷糊——或者你的書寫就不如從前準確。或者你對話的時候像在講英文，但發音開始無法匹配拼寫。</p><p><strong>LV：當你在開發 Perl 的時候，你的語言學背景會不會使你認為：“這對程序設計語言真的非常重要”？</strong></p><p>LW：我在人們是如何使用語言上想了很多。在現實的語言中，你有一套名詞、動詞和形容詞的體系，並且你知道這些單詞的詞性。在現實的自然語言中，你時常將一個單詞放到不同的位置。我所學的語言學理論也被稱為法位學（phoenetic），它解釋了這些在自然語言中工作的原理 —— 也就是有些你當做名詞的東西，有時候你可以將它用作動詞，並且人們總是這樣做。</p><p>你能很好的將任何單詞放在任何位置而進行溝通。我比較喜歡的例子是將一個整句用作為一個形容詞。這句話會是這樣的：“我不喜歡你的[我可以用任何東西來取代這個形容詞的]態度”！</p><p>所以自然語言非常靈活，因為聆聽者非常聰明 —— 至少，相對於電腦而言 —— 你相信他們會理解你最想表達的意思，即使存在歧義。當然對電腦而言，你必須保證歧義不大。</p><blockquote><p>“在 Perl 6 中，我們試圖讓電腦更準確的瞭解我們。”</p></blockquote><p>可以説在 Perl 1到5上，我們針對歧義方面處理做得還不夠。有時電腦會在不應該的時候迷惑。在 Perl 6上，我們找了許多方法，使得電腦對你所説的話能更準確的理解，就算用户並不清楚這底是字符串還是數字，電腦也能準確的知道它的類型。我們找到了內部以強類型存儲，而仍然可以無視類型的“以此即彼”的方法。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/07/wall2.jpg" alt=""></p><p><strong>LV：Perl 被視作互聯網上的“膠水（glue）”語言已久，能將點點滴滴組合在一起。在你看來 Perl 6 的發佈是否符合當前用户的需要，或者旨在招攬更多新用户，能使它重獲新生嗎？</strong></p>',19)),t("p",null,[l[4]||(l[4]=r("LW：最初的設想是為 Perl 程序員帶來更好的 Perl。但在看到了 Perl 5 上的不足後，很明顯改掉這些不足會使 Perl 6更易用，就像我在討論中提到過 —— 類似於 ",-1)),p(e,{href:"http://tinyurl.com/nhpr8g2"},{default:o(()=>[...l[3]||(l[3]=[r("托爾金（J. R. R. Tolkien） 在《指環王》前言中談到的適用性一樣",-1)])]),_:1}),l[5]||(l[5]=r("。",-1))]),l[30]||(l[30]=t("p",null,"重點是“簡單的東西應該簡單，而困難的東西應該可以實現”。讓我們回顧一下，在 Perl 2和3之間的那段時間。在 Perl 2上我們不能處理二進制數據或嵌入的 null 值 —— 只支持 C 語言風格的字符串。我曾説過“Perl 只是文本處理語言 —— 在文本處理語言裏你並不需要這些功能”。",-1)),l[31]||(l[31]=t("p",null,"但當時發生了一大堆的問題，因為大多數的文本中會包含少量的二進制數據 —— 如網絡地址（network addresses）及類似的東西。你使用二進制數據打開套接字，然後處理文本。所以通過支持二進制數據，語言的適用性（applicability）翻了一倍。",-1)),l[32]||(l[32]=t("p",null,"這讓我們開始探討在語言中什麼應該簡單。現在的 Perl 中有一條原則，是我們偷師了哈夫曼編碼（Huffman coding）的做法，它在位編碼系統中為字符采取了不同的尺寸，常用的字符佔用的位數較少，不常用的字符佔用的位數更多。",-1)),l[33]||(l[33]=t("p",null,"我們偷師了這種想法並將它作為 Perl 的一般原則，針對常用的或者説常輸入的 —— 這些常用的東西必須簡單或簡潔。不過，另一方面，也顯得更加的不規則（irregular）。在自然語言中也是這樣的，最常用的動詞實際上往往是最不規則的。",-1)),l[34]||(l[34]=t("p",null,"所以在這樣的情況下需要更多的差異存在。我很喜歡一本書是 Umberto Eco 寫的的《探尋完美的語言（The Search for the Perfect Language）》，説的並不是計算機語言；而是哲學語言，大體的意思是古代的語言也許是完美的，我們應該將它們帶回來。",-1)),l[35]||(l[35]=t("p",null,"所有的這類語言錯誤的認為類似的事物其編碼也應該總是類似的。但這並不是我們溝通的方式。如果你的農場中有許多動物，他們都有相近的名字，當你想殺一隻雞的時候説“走，去把 Blerfoo 宰了”，你的真實想法是宰了 Blerfee，但有可能最後死的是一頭牛（LCTT 譯註：這是殺雞用牛刀的意思嗎？哈哈）。",-1)),t("p",null,[l[7]||(l[7]=r("所以在這種時候我們其實更需要好好的將單詞區分開，使溝通信道的冗餘增加。常用的單詞應該有更多的差異。為了達到更有效的通訊，還有一種自足（LCTT 譯註：self-clocking ，自同步，",-1)),p(e,{href:"http://en.wikipedia.org/wiki/Self-clocking_signal"},{default:o(()=>[...l[6]||(l[6]=[r("概念",-1)])]),_:1}),l[8]||(l[8]=r("來自電信和電子行業，此處譯為“自足”更能體現涵義）編碼。如果你在一個貨物上看到過 UPC 標籤（條形碼），它就是一個自足編碼，每對“條”和“空”總是以七個列寬為單位，據此你就知道“條”的寬度加起來總是這麼寬。這就是自足。",-1))]),l[36]||(l[36]=n('<p>在電子產品中還有另一種自足編碼。在老式的串行傳輸協議中有停止和啓動位，來保持同步。自然語言中也會包含這些。比如説，在寫日語時，不用使用空格。由於書寫方式的原因，他們會在每個詞組的開頭使用中文中的漢字字符，然後用音節表（syllabary）中的字符來結尾。</p><p><strong>LV：是平假名，對嗎？</strong></p><p>LW: 是的，平假名。所以在這一系統，每個詞組的開頭就自然就很重要了。同樣的，在古希臘，大多數的動詞都是搭配好的（declined 或 conjugated），所以它們的標準結尾是一種自足機制。在他們的書寫體系中空格也是可有可無的 —— 引入空格是更近代的發明。</p><p>所以在計算機語言上也要如此，有的值也可以自足編碼。在 Perl 上我們重度依賴這種方法，而且在 Perl 6 上相較於前幾代這種依賴更重。當你使用表達式時，你要麼得到的是一個詞，要麼得到的是插值（infix）操作符。當你想要得到一個詞，你有可能得到的是一個前綴操作符，它也在相同的位置；同樣當你想要得到一個插值操作符，你也可能得到的是前一個詞的後綴。</p><p>但是反過來。如果編譯器準確的知道它想要什麼，你可以稍微重載（overload）它們，其它的讓 Perl 來完成。所以在斜線“/”後面是單詞時它會當成正則表達式，而斜線“/”在字串中時視作除法。而我們並不會重載所有東西，因為那隻會使你失去自足冗餘。</p><p>多數情況下我們提示的比較好的語法錯誤消息，是出於發現了一行中出現了兩個關鍵詞，然後我們嘗試找出為什麼一行會出現兩個關鍵字 —— “哦，你一定漏掉了上一行的分號”，所以我們相較於很多其他的按步照班的解析器可以生成更好的錯誤消息。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2015/07/wall3.jpg" alt=""></p><p><strong>LV：為什麼 Perl 6 花了15年？當每個人對事物有不同看法時一定十分難於管理，而且正確和錯誤並不是絕對的。</strong></p><p>LW：這必須要非常小心地平衡。剛開始會有許多的好的想法 —— 好吧，我並不是説那些全是好的想法。也有很多令人煩惱的地方，就像有361條 RFC [功能建議文件]，而我也許只想要20條。我們需要坐下來，將它們全部看完，並忽略其中的解決方案，因為它們通常流於表象、視野狹隘。幾乎每一條只針對一樣事物，如若我們將它們全部拼湊起來，那簡直是一堆垃圾。</p><blockquote><p>“掌握平衡時需要格外小心。畢竟在剛開始的時候總會有許多的好主意。”</p></blockquote><p>所以我們必須基於人們在使用 Perl 5 時的真實感受重新整理，尋找統一、深層的解決方案。這些 RFC 文檔許多都提到了一個事實，就是類型系統的不足。通過引入更條理分明的類型系統，我們可以解決很多問題並且即聰明又緊湊。</p><p>同時我們開始關注其他方面：如何統一特徵集並開始重用不同領域的想法，這並不需要它們在下層相同。我們有一種標準的書寫配對（pair）的方式——好吧，在 Perl 裏面有兩種！但使用冒號書寫配對的方法同樣可以用於基數計數法或是任何進制的文本編號。同樣也可以用於其他形式的引用（quoting）。在 Perl 裏我們稱它為“奇妙的一致”。</p><blockquote><p>“做了 Perl 6 的早期實現的朋友們，握着我的手説：“我們真的很需要一位語言的設計者。””</p></blockquote>',13)),t("p",null,[l[11]||(l[11]=r("同樣的想法湧現出來，你説“我已經熟悉了語法如何運作，但是我看見它也被用在別處”，所以説視角相同才能找出這種一致。那些提出各種想法和做了 Perl 6 的早期實現的人們回來看我，握着我的手説：“我們真的需要一位語言的設計者。您能作為我們的",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Benevolent_dictator_for_life"},{default:o(()=>[...l[9]||(l[9]=[r("仁慈獨裁者",-1)])]),_:1}),l[12]||(l[12]=r("（benevolent dictator）嗎？”（LCTT 譯註：Benevolent Dictator For Life，或 BDFL，指開源領袖，通常指對社區爭議擁有最終裁決權的領袖，典故來自 Python 創始人 Guido van Rossum， 具體參考維基條目",-1)),p(e,{href:"https://en.wikipedia.org/wiki/Benevolent_dictator_for_life"},{default:o(()=>[...l[10]||(l[10]=[r("解釋",-1)])]),_:1}),l[13]||(l[13]=r("）",-1))]),l[37]||(l[37]=n('<p>所以我是語言的設計者，但總是聽到：“不要管具體實現（implementation）！我們目睹了你對 Perl 5 做的那些，我們不想歷史重演！”真是讓我忍俊不禁，因為他們作為起步的核心和原先 Perl 5 的內部結構上幾乎別無二致，也許這就是為什麼一些早期的實現做的並不好的原因。</p><p>因為我們仍然在摸索我們的整個設計，其實現在做了許多 VM （虛擬機）該做什麼和不該做什麼的假設，所以最終這個東西就像面向對象的彙編語言一樣。類似的問題在伊始階段無處不在。然後 Pugs 這傢伙走過來説：“用用看 Haskell 吧，它能讓你們清醒的認識自己正在幹什麼，讓我們用它來弄清楚下層的語義模型（semantic model）。”</p><p>因此，我們明確了其中的一些語義模型，但更重要的是，我們開始建立符合那些語義模型的測試套件。在這之後，Parrot VM 繼續進行開發，並且出現了另一個實現 Niecza ，它基於 .Net，是由一個年輕的傢伙搞出來的。他很聰明，實現了 Perl 6 的一個很大的子集。不過他還是一個人幹，並沒有找到什麼好方法讓別人介入他的項目。</p><p>同時 Parrot 項目變得過於龐大，以至於任何人都不能真正的深入掌控它，並且很難重構。同時，開發 Rakudo 的人們覺得我們可能需要在更多平台上運行它，而不只是在 Parrot VM 上。 於是他們發明了所謂的可移植層 NQP ，即 “Not Quite Perl”。他們一開始將它移植到 JVM（Java虛擬機）上運行，與此同時，他們還秘密的開發了一個叫做 MoarVM 的 VM ，它去年才剛剛為人知曉。</p><p>無論 MoarVM 還是 JVM 在迴歸測試（regression test）中表現得十分接近 —— 在許多方面 Parrot 算是尾隨其後。這樣不挑剔 VM 真的很棒，我們也能開始考慮將 NQP 發揚光大。谷歌夏季編碼大賽（Google Summer of Code project）的目標就是針對 JavaScript 的 NQP，這應該靠譜，因為 MoarVM 也同樣使用 Node.js 作為日常處理。</p><p>我們可能要將今年餘下的時光投在 MoarVM 上，直到 6.0 發佈，方可休息片刻。</p><p><strong>LV：去年英國，政府開展編程年活動（Year of Code），來激發年輕人對編程的興趣。針對活動的建議五花八門——類似為了讓人們準確的認識到內存的使用你是否應該從低階語言開始講授，或是一門高階語言。你對此作何看法？</strong></p><p>LW：到現在為止，Python 社區在低階方面的教學工作做得比我們要好。我們也很想在這一方面做點什麼，這也是我們有蝴蝶 logo 的部分原因，以此來吸引七歲大小的女孩子！</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Camelia.svg/640px-Camelia.svg.png" alt="Perl 6 : Camelia"></p><blockquote><p>“到現在為止，Python 社區在低階方面的教學工作做得比我們要好。”</p></blockquote><p>我們認為將 Perl 6 作為第一門語言來學習是可行的。一大堆的將 Perl 5 作為第一門語言學習的人讓我們吃驚。你知道，在 Perl 5 中有許多相當大的概念，如閉包，詞法範圍，和一些你通常在函數式編程中見到的特性。甚至在 Perl 6 中更是如此。</p><p>Perl 6 花了這麼長時間的部分原因是我們嘗試去堅持將近 50 種互不相同的原則，在設計語言的最後對於“哪點是最重要的規則”這個問題還是懸而未決。有太多的問題需要討論。有時我們做出了決定，並已經工作了一段時間，才發現這個決定並不很正確。</p><p>之前我們並未針對併發程序設計或指定很多東西，直到 Jonathan Worthington 的出現，他非常巧妙的權衡了各個方面。他結合了一些其他語言諸如 Go 和 C# 的想法，將併發原語寫的非常好。可組合性（Composability）是一個語言至關重要的一部分。</p><p>有很多的程序設計系統的併發和並行寫的並不好 —— 比如線程和鎖，不良的操作方式有很多。所以在我看來，額外花點時間看一下 Go 或者 C# 這種高階原語的開發是很值得的 —— 那是一種關鍵字上的矛盾 —— 寫的相當棒。</p><hr>',15)),t("p",null,[l[15]||(l[15]=r("via: ",-1)),p(e,{href:"http://www.linuxvoice.com/interview-larry-wall/"},{default:o(()=>[...l[14]||(l[14]=[r("http://www.linuxvoice.com/interview-larry-wall/",-1)])]),_:1})]),t("p",null,[l[19]||(l[19]=r("作者：",-1)),p(e,{href:"http://www.linuxvoice.com/author/mike/"},{default:o(()=>[...l[16]||(l[16]=[r("Mike Saunders",-1)])]),_:1}),l[20]||(l[20]=r(" 譯者：",-1)),p(e,{href:"https://github.com/martin2011qi"},{default:o(()=>[...l[17]||(l[17]=[r("martin2011qi",-1)])]),_:1}),l[21]||(l[21]=r(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:o(()=>[...l[18]||(l[18]=[r("wxy",-1)])]),_:1})]),t("p",null,[l[24]||(l[24]=r("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[22]||(l[22]=[r("LCTT",-1)])]),_:1}),l[25]||(l[25]=r(" 原創翻譯，",-1)),p(e,{href:"https://linux.cn/"},{default:o(()=>[...l[23]||(l[23]=[r("Linux中國",-1)])]),_:1}),l[26]||(l[26]=r(" 榮譽推出",-1))])])}const y=i(P,[["render",d]]);export{k as __pageData,y as default};
